print("dup pay lines for same trip:",len(dup_pay),[(l['line_id'],l['trip_id'],l['amount']) for l in dup_pay[:5]])
# duplicate same trip same amount? partial dup (two lines, amounts differ)
for tid,v in collections.defaultdict(list).items(): pass
# incentive lines: rider-day counts, blank trip_id
inc=[l for l in lines if l['line_type']=='daily_incentive']
print("incentive lines blank trip_id:", sum(1 for l in inc if l['trip_id']==''))
pen=[l for l in lines if l['line_type']=='cancellation_penalty']
print("penalty lines blank trip_id:", sum(1 for l in pen if l['trip_id']==''), "pen with trip:", len(list(tr for tr in pen if tr['trip_id']!='')))
pen_tr=[l for l in pen if l['trip_id'] in trip_ids]
print("pen with known trip:",len(pen_tr))
for l in pen_tr[:5]: print("  ",l['line_id'],l['trip_id'],l['amount'])
