import csv, collections
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, timezone, timedelta
IST=timezone(timedelta(hours=5,minutes=30))
def ist_day(s):
    return datetime.fromisoformat(s.replace('Z','+00:00')).astimezone(IST).strftime('%Y-%m-%d')
lines=list(csv.DictReader(open('data/payout_lines.csv')))
trips=list({t['trip_id']:t for t in csv.DictReader(open('data/trips.csv'))}.values())
def fare(km, s):
    dist=max(Decimal(0), Decimal(km)-Decimal(2))
    return ((Decimal(25)+Decimal(6)*dist)*Decimal(s)).quantize(Decimal('1'), ROUND_HALF_UP)
def eff_km(t):
    d=Decimal(t['distance_km'])
    return d/1000 if d>100 else d
pay=collections.defaultdict(list)
for l in lines:
    if l['line_type']=='trip': pay[l['trip_id']].append(Decimal(l['amount']))
matched=0; mism=[]
comp=[t for t in trips if t['status']=='completed']
for t in comp:
    ls=pay.get(t['trip_id'],[])
    if not ls: continue
    f=fare(eff_km(t),t['surge_multiplier'])
    if len(ls)==1 and ls[0]==f: matched+=1
    else: mism.append((t['trip_id'],t['rider_id'],t['distance_km'],t['surge_multiplier'],[str(a) for a in ls],str(f)))
print("prorate+meters exact-match:",matched,"anomaly:",len(mism))
cats=collections.Counter()
for m in mism:
    if len(m[4])!=1: cats['multi-line']+=1; continue
    f=Decimal(m[5]); nosur=fare(Decimal(m[2]),'1.0')
    if m[3]!='1.0' and f==nosur: cats['surge_never_applied']+=1
    elif Decimal(m[4][0])<f: cats['underpaid_other']+=1
    else: cats['paid MORE than expected']+=1
print(dict(cats))
for m in mism[:10]: print("  ",m)
tl_date={l['trip_id']:l['payout_date'] for l in lines if l['line_type']=='trip'}
lags=collections.Counter(tl_date[t['trip_id']]==ist_day(t['started_at']) for t in comp if t['trip_id'] in tl_date)
print("trip line payout_date == IST trip day:",dict(lags))
EOF

